import { defineConfig } from 'vite';
import { resolve } from 'path';
import fs from 'fs';

// Find all HTML files generated by our SSG script
const getHtmlFiles = () => {
  const files = {};
  try {
    const rootFiles = fs.readdirSync(__dirname);
    rootFiles.forEach(file => {
      // Only bundle actual pages, not templates
      if (file.endsWith('.html') && !file.includes('template')) {
        const name = file.replace('.html', '');
        files[name] = resolve(__dirname, file);
      }
    });
  } catch(e) {
    console.warn("Could not read HTML files, maybe build script hasn't run yet.");
  }
  return files;
};

export default defineConfig({
  build: {
    rollupOptions: {
      input: getHtmlFiles()
    }
  }
});
